// 1. Extract & Sanitize Payload
const body = $json.body || $json;
const email = (body.email || '').trim().toLowerCase();
const name = (body.name || '').trim();
const company = (body.company || '').trim();
const message = (body.message || '').trim();
const budget = Number(body.budget) || 0;

// 2. Validation Regex
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!email || !emailRegex.test(email) || !name || !message) {
  return [{
    json: {
      isValid: false,
      errorMessage: 'Validation failed: Missing or invalid required fields (name, email, message)',
      statusCode: 400
    }
  }];
}

// 3. Domain Classification (Free vs Corporate)
const domain = email.split('@')[1];
const freeEmailDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'aol.com', 'mail.com', 'icloud.com'];
const isCorporateDomain = !freeEmailDomains.includes(domain);

// 4. Spam / Blacklist Checks
const junkKeywords = ['seo ranking', 'backlinks', 'crypto investment', 'guest post outreach', 'casino'];
const isSpam = junkKeywords.some(kw => message.toLowerCase().includes(kw));

return [{
  json: {
    isValid: true,
    isSpam: isSpam,
    email,
    name,
    company: company || 'Not Provided',
    message,
    budget,
    domain,
    isCorporateDomain,
    receivedAt: new Date().toISOString()
  }
}];

const searchResult = $input.first().json;
const leadData = $('Validate & Sanitize Payload').first().json;

let existingContactId = null;
let isDuplicate = false;

if (searchResult && searchResult.results && searchResult.results.length > 0) {
  existingContactId = searchResult.results[0].id;
  isDuplicate = true;
}

return [{
  json: {
    ...leadData,
    isDuplicate,
    existingContactId
  }
}];

