parameters.jsCode:
const leadData = $('Format Dedup Result').first().json;
const aiResponse = $input.first().json;

let aiOutput = {
  lead_score: 5,
  category: "SMB",
  intent: "General Inquiry",
  summary: leadData.message.slice(0, 100),
  suggested_response_subject: "Thank you for reaching out to us",
  suggested_response_body: `Hi ${leadData.name},\n\nThank you for reaching out. We received your message regarding: "${leadData.message}". A member of our team will review your inquiry and connect with you shortly.\n\nBest regards,\nClient Team`
};

try {
  if (aiResponse && aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
    const parsed = JSON.parse(aiResponse.choices[0].message.content);
    aiOutput = { ...aiOutput, ...parsed };
  }
} catch (e) {
  // Fallback used gracefully
}

// Deterministic Rule Boost / Penalty
let finalScore = Number(aiOutput.lead_score) || 5;
if (leadData.budget >= 10000) finalScore = Math.max(finalScore, 8);
if (leadData.isCorporateDomain) finalScore = Math.min(10, finalScore + 1);
if (leadData.isSpam) finalScore = 1;

const isHighPriority = finalScore >= 8 && !leadData.isSpam;

return [{
  json: {
    ...leadData,
    ai: aiOutput,
    finalScore,
    isHighPriority
  }
}];

